repo, err := strategy.OpenRepository(ctx)
if err != nil {
	cmd.SilenceUsage = true
	fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
	return NewSilentError(err)
}
defer repo.Close()

remote, err := repo.Remote("origin")
if err != nil {
	return fmt.Errorf("could not find 'origin' remote: %w", err)
}
urls := remote.Config().URLs
if len(urls) == 0 {
	return errors.New("origin remote has no URLs configured")
}

owner, repoName, err := search.ParseGitHubRemote(urls[0])
if err != nil {
	return fmt.Errorf("parsing remote URL: %w", err)
}

// Semantic search goes to the v4 query-serve path (entire-api
// cell gateway) via newSemanticSearcher, which fans out across
// cells and mints per-cell identity tokens itself (ENT-1055).
searcher := newSemanticSearcher(insecureHTTPAuth)

searchCfg := search.Config{
	Owner:    owner,
	Repo:     repoName,
	Repos:    repos,
	AllRepos: allRepos,
	Query:    query,
	Limit:    limitFlag,
	Page:     pageFlag,
	Author:   authorFlag,
	Date:     dateFlag,
	Branch:   branchFlag,
}

// Use wildcard query when only filters are provided
if query == "" && searchCfg.HasFilters() {
	searchCfg.Query = search.WildcardQuery
}

// No query provided + interactive = open TUI with search bar focused
if query == "" && !searchCfg.HasFilters() {
	searchCfg.Limit = search.DefaultLimit
	styles := newStatusStyles(w)
	model := newSearchModel(nil, "", 0, searchCfg, styles, buildCodeSearchOpts(ctx, owner, repoName, nil, false, insecureHTTPAuth))
	model.semanticSearch = searcher
	model.mode = modeSearch
	model.input.Focus()
	model.codeLoading = false // don't fetch until a query is entered
	p := tea.NewProgram(model)
	if _, err := p.Run(); err != nil {
		return fmt.Errorf("TUI error: %w", err)
	}
	return nil
}

// Fetch a full page (DefaultLimit, matching the web UI) up front and
// paginate client-side for all output modes; the requested --limit
// only controls the client-side page size.
requestedLimit := searchCfg.Limit
requestedPage := searchCfg.Page
searchCfg.Limit = search.DefaultLimit
searchCfg.Page = 0 // let API default to page 1

resp, err := searcher(ctx, searchCfg)
if err != nil {
	return fmt.Errorf("search failed: %w", err)
}
for _, warning := range resp.Warnings {
	fmt.Fprintln(cmd.ErrOrStderr(), "warning: "+warning)
}

// JSON output: explicit flag or piped/redirected stdout
if jsonOutput || !isTerminal {
	searchID := newSearchID()
	mode := "json"
	var served int
	var writeErr error
	if compactOutput {
		mode = "compact"
		served, writeErr = writeSearchCompactJSON(w, resp, requestedLimit, requestedPage, searchID, owner+"/"+repoName)
	} else {
		served, writeErr = writeSearchJSON(w, resp, requestedLimit, requestedPage, searchID)
	}
	if writeErr != nil {
		return writeErr
	}
	emitSearchPerformed(ctx, searchID, searchCfg.Query, mode, served, len(resp.Results), requestedPage, requestedLimit)
	return nil
}

styles := newStatusStyles(w)

// Accessible mode: static table
if IsAccessibleMode() {
	if len(resp.Results) == 0 {
		fmt.Fprintln(w, "No results found.")
		return nil
	}
	renderSearchStatic(w, resp.Results, query, resp.Total, styles)
	return nil
}

// Interactive TUI
codeOpts := buildCodeSearchOpts(ctx, owner, repoName, repos, allRepos, insecureHTTPAuth)
if codeOpts != nil {
	// Use extractInlineRepoFilters on the raw query so author:/date:/branch:
	// tokens are preserved as literal code-search text, matching --code and
	// the TUI submit path. Inline repo: filters override the flag-based
	// scope, consistent with TUI re-search behavior.
	codeQuery, inlineRepos := extractInlineRepoFilters(rawQuery)
	codeOpts.query = codeQuery // empty → no initial code search (gated in newSearchModel)
	if len(inlineRepos) > 0 {
		if hasAllReposFilter(inlineRepos) {
			codeOpts.repoFilters = nil

package cli

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/oklog/ulid/v2"
)

// Search relevance telemetry (ENT-1528). Agent-driven search has no web-style
// click signal, so two stateless events reconstruct the funnel in PostHog:
// cli_search_performed (a search served results) and cli_checkpoint_explained
// (an agent fetched one result's full detail — the "click"). Correlation
// happens entirely in the analytics layer by distinct_id + time; nothing is
// persisted locally.

// newSearchID mints a client-side search identifier. The search server
// response carries no request id (and the CLI merges several cell responses
// into one page), so the id that ties a response to its telemetry event is
// minted here. Returns "" on entropy failure; callers treat that as
// "tracking off".
func newSearchID() string {
	u, err := ulid.New(ulid.Now(), rand.Reader)
	if err != nil {
		return ""
	}
	return u.String()
}

// hashSearchQuery returns a short, non-reversible fingerprint of the query
// for telemetry: SHA-256 of the lowercased, whitespace-collapsed query,
// truncated to 16 hex chars. Raw query text is never sent (privacy
// convention: operational metadata only).
func hashSearchQuery(query string) string {
	normalized := strings.ToLower(strings.Join(strings.Fields(query), " "))
	sum := sha256.Sum256([]byte(normalized))
	return hex.EncodeToString(sum[:8])
}

// emitSearchPerformed reports a cli_search_performed telemetry event when
// telemetry is opted in (settings.Telemetry == true). Best-effort and
// non-blocking; search output has already been written, so failures simply
// suppress the event.
func emitSearchPerformed(ctx context.Context, searchID, query, mode string, resultCount, total, page, limit int) {
	if searchID == "" {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil || s.Telemetry == nil || !*s.Telemetry {
		return
	}
	telemetry.TrackSearchPerformed(telemetry.SearchPerformedEvent{
		SearchID:    searchID,
		QueryHash:   hashSearchQuery(query),
		Mode:        mode,
		ResultCount: resultCount,
		Total:       total,
		Page:        page,
		Limit:       limit,
	}, versioninfo.Version)
}

// emitCheckpointExplained reports a cli_checkpoint_explained telemetry event
// when telemetry is opted in — the "click" that follows a search impression
// (ENT-1528). Zero agent cooperation: it fires on every successful explain
// id resolution, and the search→explain funnel is assembled in the analytics
// layer. Best-effort and non-blocking; explain output is never affected.
func emitCheckpointExplained(ctx context.Context, checkpointID, source string) {
	if checkpointID == "" {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil || s.Telemetry == nil || !*s.Telemetry {
		return
	}
	telemetry.TrackCheckpointExplained(telemetry.CheckpointExplainedEvent{
		CheckpointID: checkpointID,
		Source:       source,
	}, versioninfo.Version)
}

	return runExplainCheckpointWithLookup(ctx, w, errW, checkpointIDPrefix, noPager, verbose, full, rawTranscript, generate, force, searchAll, nil, nil, summaryTimeoutSeconds)
}

func runExplainCheckpointWithLookup(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, lookup *explainCheckpointLookup, lookupErr error, summaryTimeoutSeconds int) error {
	ownLookup := false
	if lookup == nil {
		var err error
		lookup, err = newExplainCheckpointLookup(ctx)
		if err != nil {
			return err
		}
		ownLookup = true
	} else if lookupErr != nil {
		return lookupErr
	}
	initialLookup := lookup
	defer func() {
		if ownLookup && initialLookup != nil {
			_ = initialLookup.Close()
		}
		if lookup != nil && lookup != initialLookup {
			_ = lookup.Close()
		}
	}()

	// Match the prefix locally; on miss, fetch from remote and retry once.
	matches, lookup := matchCheckpointPrefixWithRemoteFallback(ctx, errW, lookup, checkpointIDPrefix)

	var fullCheckpointID id.CheckpointID
	switch len(matches) {
	case 0:
		// Check temp checkpoints BEFORE returning errCannotGenerateTemporaryCheckpoint
		// so runExplainAuto can distinguish:
		//   - target matched a real temp checkpoint (sentinel returned, no fallback)
		//   - target matched nothing (explainTargetNotFoundError, safe to fall back to commit)
		// Previously the --generate path bailed before checking temp checkpoints,
		// which made runExplainAuto fall back to commit resolution for temp
		// checkpoint SHAs and produce a misleading "no trailer" error.
		//
		// --generate and --raw-transcript are mutually exclusive at the flag
		// layer, so rawTranscript is always false when generate is true; the
		// direct-to-w write path inside explainTemporaryCheckpoint is not
		// reachable here and won't leak partial output on error.
		tempStores, openErr := checkpoint.Open(ctx, lookup.repo, checkpoint.OpenOptions{})
		if openErr != nil {
			return fmt.Errorf("open checkpoint store: %w", openErr)
		}
		output, found, tempErr := explainTemporaryCheckpoint(ctx, w, errW, lookup.repo, tempStores.Ephemeral(), checkpointIDPrefix, verbose, full, rawTranscript)
		if tempErr != nil {
			return tempErr
		}
		if found {
			if generate {
				return fmt.Errorf("%w %s (only committed checkpoints supported)", errCannotGenerateTemporaryCheckpoint, checkpointIDPrefix)
			}
			outputExplainContent(w, output, noPager)
			return nil
		}
		return &explainTargetNotFoundError{target: checkpointIDPrefix}
	case 1:
		fullCheckpointID = matches[0]
		emitCheckpointExplained(ctx, string(fullCheckpointID), telemetry.ExplainSourceProse)
	default:
		// Ambiguous prefix: render styled failure block, return SilentError so
		// main.go does not double-print. Matches the temporary-side and
		// commit-side ambiguity paths.
		ambig := buildAmbiguousCheckpointMatches(matches, lookup.committed)
		renderAmbiguousPrefixFailure(errW, checkpointIDPrefix, "committed checkpoints", ambig)
		return NewSilentError(fmt.Errorf("%w: %s matches %d checkpoints", errAmbiguousCommitPrefix, checkpointIDPrefix, len(matches)))
	}

	// Fast-fail on imported checkpoints before the expensive content load.
	// --generate is read-only-rejected for imported history, so fetching
	// transcript blobs first (prefetch + ReadLatestSessionContent inside
	// loadCheckpointForExplain) is wasted work for a guaranteed rejection.
	// Imported lives in the checkpoint metadata, so a metadata-only
	// ReadCheckpoint settles it without reading any session content. On the
	// non-imported path loadCheckpointForExplain re-reads this summary, but
	// that extra metadata-only read is cheap and happens only under
	// --generate — the skipped blob prefetch + transcript load on the

// never shows up in this repo's own checkpoint history or token profile.
//
// The output modes reuse the same renderers as the local path, so a foreign
// checkpoint prints identically to a local one.
func runCrossRepoExplain(ctx context.Context, w, errW io.Writer, opts crossRepoExplainOptions) error {
	owner, repoName, err := parseExplainRepoFlag(opts.repoFlag)
	if err != nil {
		return err
	}
	ownerRepo := owner + "/" + repoName

	// A prefix can't be resolved without listing the foreign repo's
	// checkpoints, which is `entire search`'s job, so cross-repo needs the
	// whole ID.
	cid, err := id.NewCheckpointID(opts.target)
	if err != nil {
		return fmt.Errorf("--repo requires a full checkpoint ID (12-char hex or 26-char ULID); a prefix cannot be resolved in another repo: %w", err)
	}

	reader, err := newCrossRepoReader(ctx, opts.insecureHTTP, owner, repoName)
	if err != nil {
		return err
	}
	// Marked for the renderers: a foreign checkpoint cannot be written to, so
	// they must not offer actions that only work in the owning repo.
	ctx = withCrossRepoRead(ctx, ownerRepo)

	stop := startSpinner(errW, fmt.Sprintf("Reading checkpoint %s from %s", cid, ownerRepo))
	// Read directly rather than through checkpoint.ReadCheckpoint: the helper
	// prefixes "read persistent checkpoint:", which buries the reader's
	// already-user-facing message (e.g. the not-pushed-yet guidance) behind
	// storage vocabulary that means nothing for a repo read over HTTP.
	summary, err := reader.Read(ctx, cid)
	if err != nil {
		stop(false)
		return err //nolint:wrapcheck // the reader's errors already name the checkpoint and repo
	}
	if summary == nil {
		stop(false)
		return fmt.Errorf("checkpoint %s is not available for %s", cid, ownerRepo)
	}
	emitCheckpointExplained(ctx, string(cid), telemetry.ExplainSourceCrossRepo)

	switch {
	case opts.transcript || opts.rawTranscript:
		content, contentErr := readCrossRepoSessionContent(ctx, reader, cid, summary, opts.sessionIndex)
		if contentErr != nil {
			stop(false)
			return contentErr
		}

